        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def is_perfect_square(num):
    return int(num ** 0.5) ** 2 == num

def is_fibonacci(num):
    return is_perfect_square(5 * num * num + 4) or is_perfect_square(5 * num * num - 4)

def prime_fib(n: int):
    if n < 1:
        return None

    prime_list = [2]
    fibonacci_list = [0, 1]

    num = 3
    while len(prime_list) < n or len(fibonacci_list) < n:
        if is_prime(num):
            prime_list.append(num)
        if is_fibonacci(num):
            fibonacci_list.append(num)
        num += 1

    intersection = list(set(prime_list) & set(fibonacci_list))

    if n <= len(intersection):
        return intersection[n-1]
    else:
        return None

